-- Schema only. No application data.
PRAGMA foreign_keys = OFF;
BEGIN;
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0', "suspended_at" datetime, "status" varchar not null default 'active');
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE "seats" ("id" integer primary key autoincrement not null, "event_id" integer not null, "name" varchar not null, "email" varchar not null, "seat_code" varchar not null, "created_at" datetime, "updated_at" datetime, "job_title" varchar, "organization" varchar, "location" varchar, "industry" varchar, "expectations" text, "referral_source" varchar, "phone" varchar, foreign key("event_id") references "events"("id") on delete cascade);
CREATE UNIQUE INDEX "seats_seat_code_unique" on "seats" ("seat_code");
CREATE TABLE "events" ("id" integer primary key autoincrement not null, "title" varchar not null, "subtitle" varchar, "description" text not null, "link" varchar, "event_date" date not null, "event_time" time not null, "created_at" datetime, "updated_at" datetime, "slug" varchar not null, "image" varchar, "visibility" varchar check ("visibility" in ('public', 'private')) not null default 'public', "display" varchar check ("display" in ('open_to_all', 'event_only', 'brn_only')) not null default 'event_only', "booking_fields" text);
CREATE UNIQUE INDEX "events_slug_unique" on "events" ("slug");
CREATE TABLE "telescope_entries" ("sequence" integer primary key autoincrement not null, "uuid" varchar not null, "batch_id" varchar not null, "family_hash" varchar, "should_display_on_index" tinyint(1) not null default '1', "type" varchar not null, "content" text not null, "created_at" datetime);
CREATE UNIQUE INDEX "telescope_entries_uuid_unique" on "telescope_entries" ("uuid");
CREATE INDEX "telescope_entries_batch_id_index" on "telescope_entries" ("batch_id");
CREATE INDEX "telescope_entries_family_hash_index" on "telescope_entries" ("family_hash");
CREATE INDEX "telescope_entries_created_at_index" on "telescope_entries" ("created_at");
CREATE INDEX "telescope_entries_type_should_display_on_index_index" on "telescope_entries" ("type", "should_display_on_index");
CREATE TABLE "telescope_entries_tags" ("entry_uuid" varchar not null, "tag" varchar not null, foreign key("entry_uuid") references "telescope_entries"("uuid") on delete cascade, primary key ("entry_uuid", "tag"));
CREATE INDEX "telescope_entries_tags_tag_index" on "telescope_entries_tags" ("tag");
CREATE TABLE "telescope_monitoring" ("tag" varchar not null, primary key ("tag"));
CREATE TABLE "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime, "description" text);
CREATE TABLE "blogs" ("id" integer primary key autoincrement not null, "title" varchar not null, "subtitle" varchar, "content_1" text not null, "content_2" text, "image_path" varchar, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, "slug" varchar not null, "category_id" integer, "pdf_path" varchar, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("category_id") references "categories"("id") on delete set null);
CREATE UNIQUE INDEX "blogs_slug_unique" on "blogs" ("slug");
CREATE TABLE "feedback" ("id" integer primary key autoincrement not null, "event_id" integer not null, "email" varchar not null, "rating" varchar not null, "comments" text, "created_at" datetime, "updated_at" datetime, foreign key("event_id") references "events"("id") on delete cascade);
CREATE TABLE "event_clicks" ("id" integer primary key autoincrement not null, "event_id" integer not null, "device_identifier" varchar not null, "device_type" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("event_id") references "events"("id") on delete cascade);
CREATE TABLE "event_click_logs" ("id" integer primary key autoincrement not null, "event_id" integer not null, "device_id" varchar not null, "device_type" varchar check ("device_type" in ('mobile', 'desktop')) not null, "created_at" datetime, "updated_at" datetime, foreign key("event_id") references "events"("id") on delete cascade);
CREATE TABLE "students" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "phone" varchar not null, "uniname" varchar not null, "region" varchar not null, "created_at" datetime, "updated_at" datetime, "occupation" varchar);
CREATE TABLE "activity_log" ("id" integer primary key autoincrement not null, "log_name" varchar, "description" text not null, "subject_type" varchar, "subject_id" integer, "causer_type" varchar, "causer_id" integer, "properties" text, "created_at" datetime, "updated_at" datetime, "event" varchar, "batch_uuid" varchar);
CREATE INDEX "subject" on "activity_log" ("subject_type", "subject_id");
CREATE INDEX "causer" on "activity_log" ("causer_type", "causer_id");
CREATE INDEX "activity_log_log_name_index" on "activity_log" ("log_name");
CREATE TABLE "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "permissions_name_guard_name_unique" on "permissions" ("name", "guard_name");
CREATE TABLE "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "roles_name_guard_name_unique" on "roles" ("name", "guard_name");
CREATE TABLE "model_has_permissions" ("permission_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("permission_id", "model_id", "model_type"));
CREATE INDEX "model_has_permissions_model_id_model_type_index" on "model_has_permissions" ("model_id", "model_type");
CREATE TABLE "model_has_roles" ("role_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "model_id", "model_type"));
CREATE INDEX "model_has_roles_model_id_model_type_index" on "model_has_roles" ("model_id", "model_type");
CREATE TABLE "role_has_permissions" ("permission_id" integer not null, "role_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("permission_id", "role_id"));
CREATE TABLE "brn_submissions" ("id" integer primary key autoincrement not null, "full_name" varchar not null, "email" varchar not null, "phone" varchar not null, "linkedin" varchar, "company_name" varchar not null, "country" varchar not null, "position" varchar not null, "years_of_operation" varchar not null, "number_of_employees" varchar not null, "selected_outcome" varchar not null, "goals" text, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, "name" varchar, "reg_number" varchar, "website" varchar, "year_established" integer, "industry" varchar, "categories" text, "offer_value" text, "b2b_interest" varchar not null default 'yes');
CREATE TABLE "brn_registration_tokens" ("id" integer primary key autoincrement not null, "token" varchar not null, "encrypted_data" text not null, "expires_at" datetime not null, "used" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "brn_registration_tokens_token_unique" on "brn_registration_tokens" ("token");
CREATE TABLE "playbook_downloads" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "company" varchar not null, "email_sent_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "sales_book_downloads" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_sent_at" datetime, "created_at" datetime, "updated_at" datetime, "company" varchar, "phone" varchar);
CREATE UNIQUE INDEX "sales_book_downloads_email_unique" on "sales_book_downloads" ("email");
CREATE TABLE "ultimate_funding_downloads" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "country" varchar not null, "company" varchar not null, "payment_completed" tinyint(1) not null default '0', "payment_reference" varchar, "amount_paid" numeric not null default '0', "payment_status" varchar not null default 'pending', "payment_date" datetime, "email_sent_at" datetime, "payment_data" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "contact_submissions" ("id" integer primary key autoincrement not null, "name" varchar, "email" varchar, "services" text, "message" text, "ip_address" varchar, "user_agent" varchar, "email_sent_at" datetime, "created_at" datetime, "updated_at" datetime, "phone" varchar, "company_name" varchar, "country_code" varchar, "budget_range" integer, "status" varchar not null default ('draft'), "session_id" varchar, "keystroke_count" integer not null default ('0'), "last_activity_at" datetime, "field_interactions" text, "draft_created_at" datetime, "submitted_at" datetime);
CREATE INDEX "contact_submissions_last_activity_at_index" on "contact_submissions" ("last_activity_at");
CREATE INDEX "contact_submissions_session_id_index" on "contact_submissions" ("session_id");
CREATE INDEX "contact_submissions_status_index" on "contact_submissions" ("status");
CREATE TABLE "consultations" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "payments" ("id" integer primary key autoincrement not null, "consultation_application_id" integer not null, "payment_method" varchar not null, "payment_reference" varchar not null, "amount" numeric not null, "currency" varchar not null default 'USD', "status" varchar check ("status" in ('pending', 'successful', 'failed', 'cancelled')) not null default 'pending', "payment_data" text, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("consultation_application_id") references "consultation_applications"("id") on delete cascade);
CREATE UNIQUE INDEX "payments_payment_reference_unique" on "payments" ("payment_reference");
CREATE TABLE "scheduled_sessions" ("id" integer primary key autoincrement not null, "consultation_application_id" integer not null, "session_date" date not null, "session_time" time not null, "timezone" varchar not null, "meet_link" varchar, "status" varchar check ("status" in ('scheduled', 'completed', 'cancelled', 'rescheduled')) not null default 'scheduled', "notes" text, "created_at" datetime, "updated_at" datetime, "google_calendar_event_id" varchar, "google_meet_link" text, "calendar_html_link" text, foreign key("consultation_application_id") references "consultation_applications"("id") on delete cascade);
CREATE INDEX "contact_submissions_duplicate_check" on "contact_submissions" ("email", "phone", "created_at");
CREATE TABLE "chat_messages" ("id" integer primary key autoincrement not null, "consultation_application_id" integer not null, "sender_name" varchar not null, "sender_email" varchar, "message" text not null, "sender_type" varchar check ("sender_type" in ('user', 'admin')) not null default 'user', "is_read" tinyint(1) not null default '0', "sent_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("consultation_application_id") references "consultation_applications"("id") on delete cascade);
CREATE INDEX "chat_messages_consultation_application_id_sent_at_index" on "chat_messages" ("consultation_application_id", "sent_at");
CREATE TABLE "consultation_applications" ("id" integer primary key autoincrement not null, "name" varchar, "email" varchar, "phone" varchar, "company" varchar, "industry" varchar, "business_description" text, "selected_goals" text, "selected_challenges" text, "desired_outcomes" text, "status" varchar check ("status" in ('draft', 'pending', 'payment_pending', 'paid', 'scheduled', 'completed', 'cancelled')) not null default 'pending', "created_at" datetime, "updated_at" datetime, "session_id" varchar, "draft_data" text, "draft_created_at" datetime, "submitted_at" datetime, "keystroke_count" integer not null default '0', "field_interactions" text, "ip_address" varchar, "user_agent" text, "last_activity_at" datetime, "website_or_handle" varchar);
CREATE INDEX "consultation_applications_session_id_index" on "consultation_applications" ("session_id");
CREATE INDEX "consultation_applications_status_created_at_index" on "consultation_applications" ("status", "created_at");
CREATE INDEX "consultation_applications_last_activity_at_index" on "consultation_applications" ("last_activity_at");
CREATE TABLE "projects" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "status" varchar check ("status" in ('planning', 'in_progress', 'on_hold', 'completed', 'cancelled')) not null default 'planning', "priority" varchar check ("priority" in ('low', 'medium', 'high', 'urgent')) not null default 'medium', "start_date" date, "due_date" date, "created_by" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("created_by") references "users"("id") on delete cascade);
CREATE TABLE "tasks" ("id" integer primary key autoincrement not null, "title" varchar not null, "description" text, "project_id" integer not null, "status" varchar check ("status" in ('todo', 'in_progress', 'review', 'completed')) not null default 'todo', "priority" varchar check ("priority" in ('low', 'medium', 'high', 'urgent')) not null default 'medium', "due_date" date, "created_by" integer not null, "order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("project_id") references "projects"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete cascade);
CREATE TABLE "task_user" ("id" integer primary key autoincrement not null, "task_id" integer not null, "user_id" integer not null, "assigned_by" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("task_id") references "tasks"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("assigned_by") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "task_user_task_id_user_id_unique" on "task_user" ("task_id", "user_id");
CREATE TABLE "activity_log_views" ("id" integer primary key autoincrement not null, "user_id" integer not null, "last_seen_activity_id" integer, "last_viewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "activity_log_views_user_id_unique" on "activity_log_views" ("user_id");
CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE INDEX "notifications_notifiable_type_notifiable_id_index" on "notifications" ("notifiable_type", "notifiable_id");
CREATE INDEX "notifications_notifiable_type_notifiable_id_read_at_index" on "notifications" ("notifiable_type", "notifiable_id", "read_at");
CREATE TABLE "task_comments" ("id" integer primary key autoincrement not null, "task_id" integer not null, "user_id" integer not null, "comment" text not null, "created_at" datetime, "updated_at" datetime, "parent_id" integer, "attachment_path" varchar, "attachment_name" varchar, "attachment_type" varchar, "mentioned_users" text, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("task_id") references tasks("id") on delete cascade on update no action, foreign key("parent_id") references "task_comments"("id") on delete cascade);
CREATE INDEX "task_comments_task_id_created_at_index" on "task_comments" ("task_id", "created_at");
CREATE INDEX "task_comments_parent_id_index" on "task_comments" ("parent_id");
CREATE TABLE "leads" ("id" integer primary key autoincrement not null, "first_name" varchar not null, "last_name" varchar, "email" varchar not null, "phone" varchar, "company" varchar, "job_title" varchar, "website" varchar, "country" varchar, "city" varchar, "address" varchar, "status" varchar check ("status" in ('new', 'contacted', 'qualified', 'proposal', 'negotiation', 'won', 'lost')) not null default 'new', "source" varchar check ("source" in ('website', 'referral', 'social_media', 'email_campaign', 'cold_call', 'event', 'advertisement', 'other')) not null default 'website', "priority" varchar check ("priority" in ('low', 'medium', 'high', 'urgent')) not null default 'medium', "estimated_value" numeric, "currency" varchar not null default 'USD', "interested_services" text, "requirements" text, "notes" text, "assigned_to" integer, "last_contacted_at" datetime, "next_follow_up" datetime, "converted_at" datetime, "lost_reason" varchar, "source_type" varchar, "source_id" integer, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("assigned_to") references "users"("id") on delete set null);
CREATE INDEX "leads_status_index" on "leads" ("status");
CREATE INDEX "leads_source_index" on "leads" ("source");
CREATE INDEX "leads_priority_index" on "leads" ("priority");
CREATE INDEX "leads_assigned_to_index" on "leads" ("assigned_to");
CREATE INDEX "leads_next_follow_up_index" on "leads" ("next_follow_up");
CREATE INDEX "leads_source_type_source_id_index" on "leads" ("source_type", "source_id");
CREATE UNIQUE INDEX "leads_email_unique" on "leads" ("email");
CREATE TABLE "lead_activities" ("id" integer primary key autoincrement not null, "lead_id" integer not null, "user_id" integer, "type" varchar check ("type" in ('note', 'email', 'call', 'meeting', 'task', 'status_change', 'follow_up', 'proposal_sent', 'document', 'other')) not null default 'note', "title" varchar not null, "description" text, "old_value" varchar, "new_value" varchar, "scheduled_at" datetime, "completed_at" datetime, "is_completed" tinyint(1) not null default '0', "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("lead_id") references "leads"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE INDEX "lead_activities_type_index" on "lead_activities" ("type");
CREATE INDEX "lead_activities_scheduled_at_index" on "lead_activities" ("scheduled_at");
CREATE INDEX "lead_activities_is_completed_index" on "lead_activities" ("is_completed");
CREATE TABLE "lead_emails" ("id" integer primary key autoincrement not null, "lead_id" integer not null, "user_id" integer, "from_email" varchar not null, "from_name" varchar, "to_email" varchar not null, "to_name" varchar, "subject" varchar not null, "body" text not null, "body_html" text, "direction" varchar check ("direction" in ('outgoing', 'incoming')) not null default 'outgoing', "message_id" varchar, "in_reply_to" varchar, "thread_id" varchar, "status" varchar check ("status" in ('draft', 'sent', 'delivered', 'failed', 'received')) not null default 'draft', "sent_at" datetime, "read_at" datetime, "attachments" text, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("lead_id") references "leads"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "page_visits" ("id" integer primary key autoincrement not null, "route_name" varchar not null, "page_title" varchar, "page_url" text not null, "device_type" varchar not null, "ip_address" varchar not null, "user_agent" text not null, "browser" varchar, "browser_version" varchar, "platform" varchar, "platform_version" varchar, "referrer" text, "session_id" varchar not null, "country" varchar, "city" varchar, "timezone" varchar, "latitude" numeric, "longitude" numeric, "is_unique_visitor" tinyint(1) not null default ('0'), "screen_width" integer, "screen_height" integer, "time_on_page" integer, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "page_visits_country_created_at_index" on "page_visits" ("country", "created_at");
CREATE INDEX "page_visits_device_type_created_at_index" on "page_visits" ("device_type", "created_at");
CREATE INDEX "page_visits_ip_address_created_at_index" on "page_visits" ("ip_address", "created_at");
CREATE INDEX "page_visits_route_name_created_at_index" on "page_visits" ("route_name", "created_at");
CREATE INDEX "page_visits_session_id_created_at_index" on "page_visits" ("session_id", "created_at");
CREATE TABLE "clicks" ("id" integer primary key autoincrement not null, "route_name" varchar not null, "device_type" varchar, "click_count" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "ip_address" varchar, "user_agent" text, "browser" varchar, "browser_version" varchar, "platform" varchar, "platform_version" varchar, "referrer" text, "session_id" varchar, "country" varchar, "city" varchar, "page_title" varchar, "page_url" text, "is_unique_visitor" tinyint(1) not null default ('0'), "first_visit_at" datetime, "last_visit_at" datetime);
COMMIT;
PRAGMA foreign_keys = ON;
